"""Consistent neon styling for plots generated by reproducible scripts."""
from contextlib import contextmanager
import matplotlib.pyplot as plt
from cycler import cycler

@contextmanager
def neon_style():
    params={
        'figure.facecolor':'#081220','axes.facecolor':'#0e1b2d',
        'savefig.facecolor':'#081220','axes.edgecolor':'#54708e',
        'axes.labelcolor':'#dfecf5','text.color':'#f0f6fc',
        'xtick.color':'#aac2d6','ytick.color':'#aac2d6',
        'grid.color':'#35516b','grid.alpha':.25,
        'font.family':'DejaVu Sans','font.size':10,
        'axes.prop_cycle':cycler(color=['#31f5e5','#ba90ff','#ffad5b','#69a8ff']),
        'figure.dpi':140,
    }
    with plt.rc_context(params):
        yield
